        padding: 24px;
        border-radius: 18px;
      }
    }
  </style>
</head>
<body>
  <div id="app"></div>

  <script>
    function FormField(options) {
      const describedBy = [options.helperId, options.errorId].filter(Boolean).join(" ");
      const requiredMark = options.required
        ? '<span class="required-indicator" aria-hidden="true"> *</span>'
        : "";

      return `
        <div class="form-field">
          <label for="${options.id}">${options.label}${requiredMark}</label>
          <input
            id="${options.id}"
            name="${options.name}"
            type="${options.type}"
            autocomplete="${options.autocomplete}"
            placeholder="${options.placeholder || ""}"
            ${options.required ? "required" : ""}
            aria-describedby="${describedBy}"
            aria-invalid="false"
          >
          ${options.helperText ? `<p class="field-help" id="${options.helperId}">${options.helperText}</p>` : ""}
          <p class="validation-message" id="${options.errorId}" aria-live="polite"></p>
        </div>
      `;
    }

    function SubmitButton() {
      return `
        <div class="actions">
          <button type="submit">Submit</button>
        </div>
      `;
    }

    function SupportContactForm() {
      return `
        <form id="support-contact-form" novalidate>
          ${FormField({
            id: "fullName",
            name: "fullName",
            label: "Full name",
            type: "text",
            autocomplete: "name",
            placeholder: "Jordan Lee",
            required: true,
            errorId: "fullName-error"
          })}
          ${FormField({
            id: "email",
            name: "email",
            label: "Email address",
            type: "email",
            autocomplete: "email",
            placeholder: "jordan@example.com",
            required: true,
            errorId: "email-error"
          })}
          ${FormField({
            id: "phone",
            name: "phone",
            label: "Phone number",
            type: "tel",
            autocomplete: "tel",
            placeholder: "(555) 123-4567",
            required: false,
            helperText: "Optional. Use digits with an optional country code, such as (555) 123-4567 or +1 555 123 4567.",
            helperId: "phone-help",
            errorId: "phone-error"
          })}
          ${SubmitButton()}
          <p class="status-message" id="form-status" aria-live="polite"></p>
        </form>
      `;
    }

    function SupportPage() {
      return `
        <main class="page-shell">
          <section class="support-card" aria-labelledby="support-heading">
            <h1 id="support-heading">Contact support</h1>
            <p class="intro">Send your details and our team will follow up with help for your account, billing, or technical questions.</p>
            ${SupportContactForm()}
          </section>
        </main>
      `;
    }

    function renderApp() {
      document.getElementById("app").innerHTML = SupportPage();
    }

    function validateField(field) {
      const value = field.value.trim();
      let error = "";

      if (field.name === "fullName") {
        if (!value) {
          error = "Full name is required.";
        } else if (value.length < 2) {
          error = "Enter your full name.";
        }
      }

      if (field.name === "email") {
        if (!value) {
          error = "Email address is required.";
        } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
          error = "Enter a valid email address.";
        }
      }

      if (field.name === "phone" && value) {
        if (!/^\+?[0-9()\-\s]{7,20}$/.test(value)) {
          error = "Enter a valid phone number using digits, spaces, parentheses, or hyphens.";
        }
      }

      const message = document.getElementById(field.id + "-error");
      field.setAttribute("aria-invalid", error ? "true" : "false");
      message.textContent = error;
      return !error;
    }

    function attachFormBehavior() {
      const form = document.getElementById("support-contact-form");
      const fields = Array.from(form.querySelectorAll("input"));
      const status = document.getElementById("form-status");

      fields.forEach(function(field) {
        field.addEventListener("blur", function() {
          validateField(field);
        });

        field.addEventListener("input", function() {
          if (field.getAttribute("aria-invalid") === "true") {
            validateField(field);
          }
          status.textContent = "";
        });
      });

      form.addEventListener("submit", function(event) {
        event.preventDefault();
        const isValid = fields.every(validateField);

        if (!isValid) {
          const firstInvalid = form.querySelector('[aria-invalid="true"]');
          if (firstInvalid) {
            firstInvalid.focus();
          }
          status.textContent = "Please correct the highlighted fields before submitting.";
          return;
        }

        status.textContent = "Your message is ready to send.";
      });
    }

    renderApp();
    attachFormBehavior();
  </script>
</body>
