     function validateField(field) {
       const value = field.value.trim();
       let error = "";

       if (field.name === "fullName") {
         if (!value) {
           error = "Full name is required.";
         } else if (value.length < 2) {
           error = "Enter your full name.";
         }
       }

       if (field.name === "email") {
         if (!value) {
           error = "Email address is required.";
         } else if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) {
           error = "Enter a valid email address.";
         }
       }

       if (field.name === "phone" && value) {
         if (!/^\+?[0-9()\-\s]{7,20}$/.test(value)) {
           error = "Enter a valid phone number using digits, spaces, parentheses, or hyphens.";
         }
       }

       const message = document.getElementById(field.id + "-error");
       field.setAttribute("aria-invalid", error ? "true" : "false");
       message.textContent = error;
       return !error;
     }

     function attachFormBehavior() {
       const form = document.getElementById("support-contact-form");
       const fields = Array.from(form.querySelectorAll("input"));
       const status = document.getElementById("form-status");

       fields.forEach(function(field) {
         field.addEventListener("blur", function() {
           validateField(field);
         });

         field.addEventListener("input", function() {
           if (field.getAttribute("aria-invalid") === "true") {
             validateField(field);
           }
           status.textContent = "";
         });
       });

       form.addEventListener("submit", function(event) {
         event.preventDefault();
         const isValid = fields.every(validateField);

         if (!isValid) {
           const firstInvalid = form.querySelector('[aria-invalid="true"]');
           if (firstInvalid) {
             firstInvalid.focus();
           }
           status.textContent = "Please correct the highlighted fields before submitting.";
